4609|    ret = xmlNewDoc(doc->version);
4610|    if (ret == NULL) return(NULL);
4611|    ret->type = doc->type;
4612|    if (doc->name != NULL) {
4613|        ret->name = xmlMemStrdup(doc->name);
4614|        if (ret->name == NULL)
4615|            goto error;
4616|    }
4617|    if (doc->encoding != NULL) {
4618|        ret->encoding = xmlStrdup(doc->encoding);
4619|        if (ret->encoding == NULL)
4620|            goto error;
4621|    }
4622|    if (doc->URL != NULL) {
4623|        ret->URL = xmlStrdup(doc->URL);
4624|        if (ret->URL == NULL)
4625|            goto error;
4626|    }
4627|    ret->charset = doc->charset;
4628|    ret->compression = doc->compression;
4629|    ret->standalone = doc->standalone;
4630|    if (!recursive) return(ret);
4631|
4632|    ret->last = NULL;
4633|    ret->children = NULL;
4634|#ifdef LIBXML_TREE_ENABLED
4635|    if (doc->intSubset != NULL) {
4636|        ret->intSubset = xmlCopyDtd(doc->intSubset);
4637|	if (ret->intSubset == NULL)
4638|            goto error;
4639|	xmlSetTreeDoc((xmlNodePtr)ret->intSubset, ret);
4640|	ret->intSubset->parent = ret;
4641|    }
4642|#endif
4643|    if (doc->oldNs != NULL) {
4644|        ret->oldNs = xmlCopyNamespaceList(doc->oldNs);
4645|        if (ret->oldNs == NULL)
4646|            goto error;
4647|    }
4648|    if (doc->children != NULL) {
4649|	xmlNodePtr tmp;
4650|
4651|	ret->children = xmlStaticCopyNodeList(doc->children, ret,
4652|		                               (xmlNodePtr)ret);
4653|        if (ret->children == NULL)
4654|            goto error;
4655|	ret->last = NULL;
4656|	tmp = ret->children;
4657|	while (tmp != NULL) {
